(async () => {
  const real = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const url = new URL(typeof input === 'string' ? input : input.url, location.href);
    if (url.pathname === '/api/instances' && url.searchParams.get('fresh') === '1') {
      return new Response(JSON.stringify({ error: 'The engine check timed out.' }), { status: 503, headers: { 'content-type': 'application/json' } });
    }
    const response = await real(input, init);
    if (url.pathname !== '/api/instances') return response;
    const body = await response.clone().json();
    for (const instance of body.instances ?? []) instance.snapshot = { ...instance.snapshot, state: 'unavailable' };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  };
  window.dispatchEvent(new Event('focus'));
  return true;
})()
